import pandas as pd
import numpy as np

def clean_value(val):
    if pd.isna(val):
        return np.nan
    if isinstance(val, str):
        val = val.replace(',', '.')
    try:
        return float(val)
    except:
        return np.nan

df = pd.read_csv('/root/environment/data/ckd_lab_data.csv')
for col in df.columns:
    df[col] = df[col].apply(clean_value)

# Drop rows with any NaN
df_dropped = df.dropna()

print(f"Original rows: {len(df)}")
print(f"Rows after dropping NaNs: {len(df_dropped)}")

stats = df_dropped.describe().T
print(stats[['min', 'max', 'mean', 'std']])

